package com.anve.app.data.auth

import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.UUID

/**
 * The installation identity semantics (ADR 0004): stable while app data
 * exists, regenerated by a reinstall. "Reinstall" is modelled by a fresh
 * store; nothing here reads a hardware identifier.
 */
class DeviceIdentityTest {

    private class FakeStore(var stored: String? = null) : InstallationIdStore {
        var writes = 0
        override suspend fun read(): String? = stored
        override suspend fun write(id: String) {
            stored = id
            writes++
        }
    }

    @Test
    fun `generates once and stays stable`(): Unit = runBlocking {
        val store = FakeStore()
        val identity = DeviceIdentity(store)

        val first = identity.deviceId()
        val second = identity.deviceId()

        assertEquals(first, second)
        assertEquals("the id is written exactly once", 1, store.writes)
        UUID.fromString(first) // throws if not a UUID
    }

    @Test
    fun `reuses an existing id without writing`(): Unit = runBlocking {
        val existing = UUID.randomUUID().toString()
        val store = FakeStore(stored = existing)
        val identity = DeviceIdentity(store)

        assertEquals(existing, identity.deviceId())
        assertEquals(0, store.writes)
    }

    @Test
    fun `a process restart over the same storage keeps the id`(): Unit = runBlocking {
        val store = FakeStore()
        val first = DeviceIdentity(store)
        val id = first.deviceId()

        // New instance, same persisted storage: the identity survives.
        val restarted = DeviceIdentity(store)
        assertEquals(id, restarted.deviceId())
    }

    @Test
    fun `a reinstall produces a new installation id`(): Unit = runBlocking {
        val before = DeviceIdentity(FakeStore()).deviceId()
        val after = DeviceIdentity(FakeStore()).deviceId()

        assertNotEquals("private storage is gone after a reinstall", before, after)
    }

    @Test
    fun `registration carries the installation id and platform`(): Unit = runBlocking {
        val identity = DeviceIdentity(FakeStore()) { "Pixel 8" }

        val registration = identity.registration()

        assertEquals(identity.deviceId(), registration.clientDeviceId)
        assertEquals("android", registration.platform)
        assertEquals("Pixel 8", registration.name)
    }
}
